mapper.select:
SELECT FROM student_order o JOIN sys_user u ON u.id = o.student_id AND u.deleted = 0 LEFT JOIN user_semester_profile p ON p.user_id = o.student_id AND p.semester_id = o.semester_id AND p.deleted = 0 LEFT JOIN college c ON c.id = p.college_id AND c.deleted = 0 LEFT JOIN school_class sc ON sc.id = p.class_id AND sc.deleted = 0 WHERE o.deleted = 0 AND o.semester_id = #{semesterId}
AND EXISTS (SELECT 1 FROM user_semester_profile p3 WHERE p3.user_id = o.student_id AND p3.semester_id = o.semester_id AND p3.college_id = #{collegeId} AND p3.deleted = 0)
AND EXISTS (SELECT 1 FROM user_semester_profile p4 WHERE p4.user_id = o.student_id AND p4.semester_id = o.semester_id AND p4.class_id = #{classId} AND p4.deleted = 0)
AND u.name LIKE CONCAT(#{studentName}, '%') ESCAPE '|' ORDER BY o.submitted_at DESC, o.id DESC LIMIT #{limit} OFFSET #{offset}
